  def genTestSuite(testCases: ISZ[(Z, ISZ[ST])]): Unit = {
    val tq = "\"\"\""

    val testRoot = Os.path(".") / "src" / "test" / "bridge"

    val Upstream_Acquisition_Qualification_image_availability_process_upstream_acquisition_qualification_id = Arch.EIT_Image_Availability_System_Instance_image_availability_process_upstream_acquisition_qualification.id
    val Doctor_Intent_Qualification_image_availability_process_doctor_intent_qualification_id = Arch.EIT_Image_Availability_System_Instance_image_availability_process_doctor_intent_qualification.id
    val Generation_Result_Qualification_image_availability_process_generation_result_qualification_id = Arch.EIT_Image_Availability_System_Instance_image_availability_process_generation_result_qualification.id
    val Image_Availability_Governor_image_availability_process_image_availability_governor_id = Arch.EIT_Image_Availability_System_Instance_image_availability_process_image_availability_governor.id
    val Generation_Directive_Derivation_image_availability_process_generation_directive_derivation_id = Arch.EIT_Image_Availability_System_Instance_image_availability_process_generation_directive_derivation.id
    val Doctor_Publication_image_availability_process_doctor_publication_id = Arch.EIT_Image_Availability_System_Instance_image_availability_process_doctor_publication.id

    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case Upstream_Acquisition_Qualification_image_availability_process_upstream_acquisition_qualification_id =>
          val prefix = "Upstream_Acquisition_Qualification_image_availability_process_upstream_acquisition_qualification_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","EIT_Image_Availability_Coordinator")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.EIT_Image_Availability_Coordinator
                |
                |import org.sireum._
                |import scp_candidate.EIT_Image_Availability_Coordinator._
                |
                |class ${suiteName} extends Upstream_Acquisition_Qualification_image_availability_process_upstream_acquisition_qualification_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case Doctor_Intent_Qualification_image_availability_process_doctor_intent_qualification_id =>
          val prefix = "Doctor_Intent_Qualification_image_availability_process_doctor_intent_qualification_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","EIT_Image_Availability_Coordinator")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.EIT_Image_Availability_Coordinator
                |
                |import org.sireum._
                |import scp_candidate.EIT_Image_Availability_Coordinator._
                |
                |class ${suiteName} extends Doctor_Intent_Qualification_image_availability_process_doctor_intent_qualification_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case Generation_Result_Qualification_image_availability_process_generation_result_qualification_id =>
          val prefix = "Generation_Result_Qualification_image_availability_process_generation_result_qualification_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","EIT_Image_Availability_Coordinator")
