          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case Image_Availability_Governor_image_availability_process_image_availability_governor_id =>
          val prefix = "Image_Availability_Governor_image_availability_process_image_availability_governor_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","EIT_Image_Availability_Coordinator")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
