        case Doctor_Publication_image_availability_process_doctor_publication_id =>
          val prefix = "Doctor_Publication_image_availability_process_doctor_publication_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","EIT_Image_Availability_Coordinator")
